mapper.select:
SELECT ci.id, ci.code, ci.name, short_name, area_id, country_id, province_id, city_id, seller_id, seller_name, business_mode, ci.platform_type as platformType, company_category_dict, approve_status, ci.disabled, use_org_id, use_org_name, group_name, inner_org_id, inner_org_name, customer_property, mail_address, approve_user_name, ci.create_user_id, ci.create_user_name, ci.create_time, ci.country_id, ccp.partition_id as partitionId, ccp.partition_code as partitionCode, ccp.partition_name as partitionName, ci.sales_dept_id as salesDeptId FROM customer_info ci left join foreign_cfg_country_partition ccp on ccp.country = ci.country_id and ccp.is_deleted = false and ccp.disabled = false WHERE ${params.sqlMap.default} and ci.is_deleted=FALSE
${params.permissionSql}
ORDER BY ci.create_time DESC

SELECT approve_status, count(*) FROM customer_info ci WHERE is_deleted=FALSE
${permissionSql}
GROUP BY approve_status

select ci.id, ci.name, ci.code, cc.person, cc.position, cc.tel_number as personTelNumber, cc.email as personEmail, cc.is_default as personIsDefault, cc.disabled as personDisabled, cc.remark as personRemark, ca.address, ca.type, ca.tel_number as addressTelNumber, ca.email as addressEmail, ca.is_default as addressIsDefault, ca.disabled as addressDisabled, ca.remark as addressRemark from customer_info ci inner join customer_address ca on ci.id = ca.main_id and ca.is_deleted = false inner join customer_contact cc on ci.id = cc.main_id and cc.is_deleted = false where ci.is_deleted = false and cc.person = ca.person
and ci.id IN
#{id}
